class Solution {
  public int minPenalty(int period, int[] lights, int[] arrivalTime) {
    int green = 0;
    for (int l : lights) green = Math.max(green, l);
    int worst = 0;
    for (int t : arrivalTime) {
      int r = t % period;
      if (r >= green) worst = Math.max(worst, period - r);
    }
    return worst;
  }
}
